//! Built-in exercise library and muscle taxonomy, embedded at compile time.
//! Generated by `scripts/build_library.py`.

use std::sync::OnceLock;

use serde::{Deserialize, Serialize};

const EXERCISES_JSON: &str = include_str!("../../../data/library/exercises.json");
const MUSCLES_JSON: &str = include_str!("../../../data/library/muscles.json");

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LibraryExercise {
    pub slug: String,
    pub name: String,
    pub aliases: Vec<String>,
    pub equipment: String,
    pub pattern: String,
    pub kind: String,
    pub primary: Vec<String>,
    pub secondary: Vec<String>,
    /// "liftbook" (curated, the id predates the FitLedger name) or "free-exercise-db" (muscles auto-mapped).
    pub source: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MuscleGroup {
    pub id: String,
    pub name: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Muscle {
    pub id: String,
    pub name: String,
    pub group: String,
}

#[derive(Debug, Deserialize)]
pub struct Library {
    pub attribution: String,
    pub exercises: Vec<LibraryExercise>,
    #[serde(skip)]
    pub groups: Vec<MuscleGroup>,
    #[serde(skip)]
    pub muscles: Vec<Muscle>,
}

#[derive(Deserialize)]
struct MusclesFile {
    groups: Vec<MuscleGroup>,
    muscles: Vec<Muscle>,
}

pub fn library() -> &'static Library {
    static LIB: OnceLock<Library> = OnceLock::new();
    LIB.get_or_init(|| {
        let mut lib: Library = serde_json::from_str(EXERCISES_JSON).expect("embedded exercises.json is valid");
        let m: MusclesFile = serde_json::from_str(MUSCLES_JSON).expect("embedded muscles.json is valid");
        lib.groups = m.groups;
        lib.muscles = m.muscles;
        lib
    })
}

/// Changes whenever the embedded library changes; used to decide when to re-seed the database.
pub fn version() -> u64 {
    // FNV-1a: stable across Rust versions, unlike `DefaultHasher`.
    EXERCISES_JSON.bytes().chain(MUSCLES_JSON.bytes()).fold(0xcbf2_9ce4_8422_2325, |h, b| {
        (h ^ b as u64).wrapping_mul(0x0100_0000_01b3)
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn library_is_consistent() {
        let lib = library();
        assert!(lib.exercises.len() > 500);
        let muscles: HashSet<_> = lib.muscles.iter().map(|m| m.id.as_str()).collect();
        let groups: HashSet<_> = lib.groups.iter().map(|g| g.id.as_str()).collect();
        assert!(lib.muscles.iter().all(|m| groups.contains(m.group.as_str())));
        let mut slugs = HashSet::new();
        for e in &lib.exercises {
            assert!(slugs.insert(e.slug.as_str()), "duplicate slug {}", e.slug);
            for m in e.primary.iter().chain(&e.secondary) {
                assert!(muscles.contains(m.as_str()), "{}: unknown muscle {m}", e.name);
            }
        }
    }
}
